using System.Collections.Concurrent;
using Apogeu.BuildingBlocks.Contracts;
using Apogeu.Operators.Contracts;
using Apogeu.Security.Tests.Support;

namespace Apogeu.Wallet.Tests.Support;

/// <summary>
/// Double of the operator wallet configuration (SPEC-0046 §6: <c>walletMode demo|seamless</c>, default demo, and the wallet
/// URL of SPEC-0038): every operator is demo unless the test turns it seamless with the URL of the operator test server and
/// an API key generated by the test (never a real credential, ADR-0014).
/// </summary>
internal sealed class FixedOperatorWalletSettings : IOperatorWalletSettings
{
    private static readonly OperatorWalletSettings DemoSettings = new(WalletMode.Demo, WalletUrl: null, Key: null);

    private readonly ConcurrentDictionary<OperatorId, OperatorWalletSettings> _settings = new();

    /// <summary>Turns <paramref name="op"/> seamless: its wallet is at <paramref name="walletUrl"/> and the calls are signed with <paramref name="key"/>.</summary>
    public FixedOperatorWalletSettings UseSeamless(OperatorId op, Uri walletUrl, TestApiKey key)
    {
        ArgumentNullException.ThrowIfNull(key);
        _settings[op] = new OperatorWalletSettings(WalletMode.Seamless, walletUrl, new OperatorWalletKey(key.Id, key.Secret));
        return this;
    }

    public Task<OperatorWalletSettings> GetAsync(OperatorId op, CancellationToken ct) =>
        Task.FromResult(_settings.TryGetValue(op, out var settings) ? settings : DemoSettings);
}
